// routing_provider.go retains only the route-health and ordering helpers
// consumed by routing_smart.go and the route-status command.
//
// As of ADR-005 step 3, the CLI no longer wraps providers with a
// per-Chat failover routeProvider. Provider failover is owned by the
// service-side smart routing engine; the CLI's job is to surface the
// top-scored candidate and let the engine decide on retry. The legacy
// `routeProvider` (an `agentcore.Provider` implementation), its
// `newRouteProvider`/`buildCandidate`/`recordAttempt`/`markCandidateFailure`
// helpers, and the `routeError`/`shouldFailover`/`withModelOverride`
// utilities have all been removed. The structural test
// `TestCLIRoutingProviderHasNoCoreProviderImpl` asserts they do not
// re-enter this file.

import (
	"encoding/json"
	"path/filepath"
	"strings"
	"time"

	agentConfig "github.com/DocumentDrivenDX/fizeau/internal/config"
	"github.com/DocumentDrivenDX/fizeau/internal/safefs"
)

const defaultRouteHealthCooldown = 30 * time.Second

type routeHealthState struct {
	Failures map[string]time.Time `json:"failures,omitempty"`
}

func routeAttemptOrder(route routePlanConfig, counter int, state routeHealthState, cooldown time.Duration) []int {
	switch route.Strategy {
	case "priority-round-robin":
		return priorityRoundRobinOrder(route.Candidates, counter, state, cooldown)
	default:
		return orderedFailoverOrder(route.Candidates, state, cooldown)
	}
}

func priorityRoundRobinOrder(candidates []routePlanCandidate, counter int, state routeHealthState, cooldown time.Duration) []int {
	eligible := healthyCandidateIndexes(candidates, state, cooldown)
	if len(eligible) == 0 {
		eligible = make([]int, len(candidates))
		for i := range candidates {
			eligible[i] = i
		}
	}
	bestPriority := candidates[eligible[0]].Priority
	for _, idx := range eligible[1:] {
		if candidates[idx].Priority > bestPriority {
			bestPriority = candidates[idx].Priority
		}
	}
	var preferred []int
	var remainder []int
	for _, idx := range eligible {
		if candidates[idx].Priority == bestPriority {
			preferred = append(preferred, idx)
		} else {
			remainder = append(remainder, idx)
		}
	}
	if len(preferred) == 0 {
		return remainder
	}
	rotated := append([]int(nil), preferred...)
	if len(rotated) > 1 {
		offset := counter % len(rotated)
		rotated = append(rotated[offset:], rotated[:offset]...)
	}
	return append(rotated, remainder...)
}

func orderedFailoverOrder(candidates []routePlanCandidate, state routeHealthState, cooldown time.Duration) []int {
	eligible := healthyCandidateIndexes(candidates, state, cooldown)
	if len(eligible) > 0 {
		return eligible
	}
	order := make([]int, len(candidates))
	for i := range candidates {
		order[i] = i
	}
	return order
}

func healthyCandidateIndexes(candidates []routePlanCandidate, state routeHealthState, cooldown time.Duration) []int {
	now := time.Now().UTC()
	var eligible []int
	for i, candidate := range candidates {
		failedAt, ok := state.Failures[candidate.Provider]
		if !ok || now.Sub(failedAt) >= cooldown {
			eligible = append(eligible, i)
		}
	}
	return eligible
}

func routeHealthStateFile(workDir, routeKey string) string {
	return agentConfig.ProjectRouteHealthPath(workDir, routeStateKey(routeKey))
}

func loadRouteHealthState(workDir, routeKey string) (routeHealthState, error) {
	path := routeHealthStateFile(workDir, routeKey)
	data, err := safefs.ReadFile(path)
	if err != nil {
		return routeHealthState{Failures: make(map[string]time.Time)}, nil
	}
	var state routeHealthState
	if err := json.Unmarshal(data, &state); err != nil {
		return routeHealthState{Failures: make(map[string]time.Time)}, nil
	}
	if state.Failures == nil {
		state.Failures = make(map[string]time.Time)
	}
	return state, nil
}

func saveRouteHealthState(workDir, routeKey string, state routeHealthState) error {
	path := routeHealthStateFile(workDir, routeKey)
	if err := safefs.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return err
	}
	data, err := json.Marshal(state)
	if err != nil {
		return err
	}
	// WriteFileAtomic prevents readers from seeing a partially-written file
	// if the process is interrupted between write and flush.
	return safefs.WriteFileAtomic(path, data, 0o600)
}

func routeHealthCooldown(cfg *agentConfig.Config) time.Duration {
	if cfg == nil || strings.TrimSpace(cfg.Routing.HealthCooldown) == "" {
		return defaultRouteHealthCooldown
	}
	d, err := time.ParseDuration(cfg.Routing.HealthCooldown)
	if err != nil || d <= 0 {
		return defaultRouteHealthCooldown
	}
	return d
}

func routeStateKey(routeName string) string {
	replacer := strings.NewReplacer("/", "_", ":", "_", " ", "_")
	return replacer.Replace(routeName)
}

package core

import (
	"errors"
	"regexp"
)

// overflowPattern matches error messages that indicate the request exceeded the
// model's context window.
var overflowPattern = regexp.MustCompile(
	`(?i)context.?length|token.?limit|maximum.?context|context.?window|` +
		`too.?long|exceeds.*limit|reduce.*length|reduce.*message`,
)

// IsContextOverflowError reports whether err indicates the request exceeded
// the model's context window.
func IsContextOverflowError(err error) bool {
	if err == nil {
		return false
	}
	return overflowPattern.MatchString(err.Error())
}

// transientPattern matches error messages that indicate a transient condition
// (network blips, rate limits, server overload) that is safe to retry.
var transientPattern = regexp.MustCompile(
	`(?i)overloaded|rate.?limit|too many requests|429|500|502|503|504|` +
		`service.?unavailable|server.?error|internal.?error|` +
		`network.?error|connection.?error|connection.?refused|` +
		`other side closed|fetch failed|socket hang.?up|` +
		`ended without|timed?.?out|timeout|i/o timeout|` +
		`EOF|connection reset|broken pipe`,
)

// fatalPattern matches error messages that indicate a permanent failure
// (authentication/authorization). These should never be retried even if they
// also match a transient pattern.
var fatalPattern = regexp.MustCompile(
	`(?i)401|403|unauthorized|forbidden|invalid.?api.?key|authentication`,
)

// IsTransientError reports whether err is a transient provider error
// that is safe to retry (network issues, rate limits, server overload).
// Returns false for fatal errors (auth failures, bad requests, etc.).
func IsTransientError(err error) bool {
	if err == nil {
		return false
	}
	// Provider-capability errors are deterministic for a given provider+model
	// combination. Retrying just burns the same call repeatedly with the same
	// outcome, so classify them as non-transient regardless of substring shape.
	if errors.Is(err, ErrProviderCapabilityMissing) {
		return false
	}
	msg := err.Error()
	if fatalPattern.MatchString(msg) {
		return false
	}
	return transientPattern.MatchString(msg)
}

	seq++

	if ctx.Err() != nil {
		result.Status = StatusCancelled
		result.Duration = time.Since(start)
		snapshotMessages()
		emitFinalSessionEnd(req.Callback, sessionID, &seq, req.Provider, &result, req.Metadata)
		return result, nil
	}

	// Reasoning loop detection: the model produced only reasoning
	// tokens past the byte or stall threshold. Log a warning and stop
	// looping — this is non-retryable and should not count as an error
	// in benchmark mode.
	if errors.Is(err, ErrReasoningOverflow) || errors.Is(err, ErrReasoningStall) {
		slog.Warn("reasoning loop detected: aborting stream", "err", err)
		result.Status = StatusError
		result.Error = fmt.Errorf("agent: %w", err)
		result.Duration = time.Since(start)
		snapshotMessages()
		emitFinalSessionEnd(req.Callback, sessionID, &seq, req.Provider, &result, req.Metadata)
		return result, result.Error
	}

	// Overflow recovery: when the provider signals a context overflow
	// and we haven't already attempted overflow-compaction this turn,
	// run compaction and retry the provider call once. Only one attempt
	// per turn to prevent infinite loops.
	if IsContextOverflowError(err) && !overflowCompacted && req.Compactor != nil {
		overflowCompacted = true
		compacted, _, compErr := runCompaction(false)
		if compErr != nil {
			// ErrCompactionNoFit or other fatal compaction error.
			result.Status = StatusError
			result.Error = fmt.Errorf("agent: provider error: %w", err)
			result.Duration = time.Since(start)
			snapshotMessages()
			emitFinalSessionEnd(req.Callback, sessionID, &seq, req.Provider, &result, req.Metadata)
			return result, result.Error
		}
		if compacted {
			// Rebuild providerMessages from the freshly compacted history.
			providerMessages = append([]Message(nil), messages...)
			if req.SystemPrompt != "" {
				providerMessages = append([]Message{{
					Role:    RoleSystem,
					Content: req.SystemPrompt,
				}}, providerMessages...)
			}
			attempt = 0 // incremented to 1 by the loop header
			continue providerRetry
		}
		// Compactor ran but produced no shorter history — fall through to error.
	}

	if !IsTransientError(err) {
		result.Status = StatusError
		result.Error = fmt.Errorf("agent: provider error: %w", err)
		result.Duration = time.Since(start)
		snapshotMessages()
		emitFinalSessionEnd(req.Callback, sessionID, &seq, req.Provider, &result, req.Metadata)
		return result, result.Error
	}

	if attempt < maxProviderAttempts {
		delaySeconds := time.Duration(1 << min(attempt-1, 10))
		delay := time.Second * delaySeconds
		slog.Warn("provider error, retrying", "attempt", attempt, "err", err, "delay", delay)
		select {
		case <-ctx.Done():
			result.Status = StatusCancelled
			result.Duration = time.Since(start)
			snapshotMessages()
			emitFinalSessionEnd(req.Callback, sessionID, &seq, req.Provider, &result, req.Metadata)
			return result, nil
		case <-time.After(delay):
		}
		continue
	}

	result.Status = StatusError
	result.Error = fmt.Errorf("agent: provider error: %w", err)
	result.Duration = time.Since(start)
	snapshotMessages()
	emitFinalSessionEnd(req.Callback, sessionID, &seq, req.Provider, &result, req.Metadata)
	return result, result.Error
}

